void RemoteObjectAsyncWaiter::HasMethod(
    const ::blink::String& name, bool* out_method_exists) {
  base::RunLoop loop;
  proxy_->HasMethod(
      std::move(name),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_method_exists
,
             bool method_exists) {*out_method_exists = std::move(method_exists);
            loop->Quit();
          },
          &loop,
          out_method_exists));
  loop.Run();
}

bool RemoteObjectAsyncWaiter::HasMethod(
    const ::blink::String& name) {
  bool async_wait_result;
  HasMethod(std::move(name),&async_wait_result);
  return async_wait_result;
}

void RemoteObjectAsyncWaiter::GetMethods(
    ::blink::Vector<::blink::String>* out_method_names) {
  base::RunLoop loop;
  proxy_->GetMethods(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::blink::Vector<::blink::String>* out_method_names
,
             const ::blink::Vector<::blink::String>& method_names) {*out_method_names = std::move(method_names);
            loop->Quit();
          },
          &loop,
          out_method_names));
  loop.Run();
}

::blink::Vector<::blink::String> RemoteObjectAsyncWaiter::GetMethods(
    ) {
  ::blink::Vector<::blink::String> async_wait_result;
  GetMethods(&async_wait_result);
  return async_wait_result;
}

void RemoteObjectAsyncWaiter::InvokeMethod(
    const ::blink::String& name, ::blink::Vector<RemoteInvocationArgumentPtr> arguments, RemoteInvocationResultPtr* out_result) {
  base::RunLoop loop;
  proxy_->InvokeMethod(
      std::move(name),
      std::move(arguments),
      base::BindOnce(
          [](base::RunLoop* loop,
             RemoteInvocationResultPtr* out_result
,
             RemoteInvocationResultPtr result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

RemoteInvocationResultPtr RemoteObjectAsyncWaiter::InvokeMethod(
    const ::blink::String& name, ::blink::Vector<RemoteInvocationArgumentPtr> arguments) {
  RemoteInvocationResultPtr async_wait_result;
  InvokeMethod(std::move(name),std::move(arguments),&async_wait_result);
  return async_wait_result;
}




